-- =============================================================================
-- svetikony — D1 seed data: Old Slavonic alphabet (46 letters x uk/ru/en)
-- =============================================================================
-- Ported from ../../assistant/migrations/20260715000001_church_alphabet.sql
-- (seed content only — the table/indexes/trigger come from
-- 0001_svetikony_schema.sql). Content of every letter is untouched; only the
-- SQL shape changed:
--   - dropped the `site_id` column/value (this D1 database is svetikony-only)
--   - dropped the `is_global` column/value (no other site to be global across)
--   - the original used one `WITH grouped AS (...)` CTE + a single 138-row
--     INSERT so all 3 language rows of a letter could share one
--     gen_random_uuid() via a subselect. Trying that same shape verbatim in
--     SQLite hit "parser stack overflow" (D1's SQLite parser has a much
--     lower recursion limit than Postgres for deeply-nested VALUES/CTEs).
--     Fix: the 46 translation-group UUIDs are pre-generated below as literal
--     values (no CTE, no subselect), and the INSERT is batched into 15-row
--     statements — both changes are purely mechanical, no data changed.
-- =============================================================================

INSERT INTO church_alphabet_letters
    (slug, letter, sort_order, name, short_description, full_text, numeric_value,
     modern_equivalent, color, card_image_url, main_image_url, seo_title, seo_description,
     language, translation_group_id, status)
VALUES
    ('az', 'А', 1, 'Азъ', 'Я, початок, людина', 'Азъ — знак старословʼянської азбуки. Його сенс: Я, початок, людина. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'А', '#9a2b1e', '', '', '', '', 'uk', '08123a57-f25f-4983-8d22-0086989d97ae', 'published'),
    ('az', 'А', 1, 'Азъ', 'Я, начало, человек', 'Азъ напоминает, что познание начинается с личности и ответственности человека перед Богом, словом и делом.', NULL, 'А', '#9a2b1e', '', '', '', '', 'ru', '08123a57-f25f-4983-8d22-0086989d97ae', 'published'),
    ('az', 'А', 1, 'Азъ', 'I, beginning, person', 'Азъ is a sign of the Old Slavonic alphabet. Its meaning: I, beginning, person. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'А', '#9a2b1e', '', '', '', '', 'en', '08123a57-f25f-4983-8d22-0086989d97ae', 'published'),
    ('buki', 'Б', 2, 'Буки', 'Літери, знання, письмо', 'Буки — знак старословʼянської азбуки. Його сенс: Літери, знання, письмо. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Б', '#1f3f66', '', '', '', '', 'uk', '16ee06e3-456d-4d47-bd56-c6bff0cfc83b', 'published'),
    ('buki', 'Б', 2, 'Буки', 'Буквы, знание, письмо', 'Буки открывает путь к письменной памяти: через буквы сохранялись молитвы, книги и церковное предание.', NULL, 'Б', '#1f3f66', '', '', '', '', 'ru', '16ee06e3-456d-4d47-bd56-c6bff0cfc83b', 'published'),
    ('buki', 'Б', 2, 'Буки', 'Letters, knowledge, writing', 'Буки is a sign of the Old Slavonic alphabet. Its meaning: Letters, knowledge, writing. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Б', '#1f3f66', '', '', '', '', 'en', '16ee06e3-456d-4d47-bd56-c6bff0cfc83b', 'published'),
    ('vedi', 'В', 3, 'Веди', 'Відаю, знаю', 'Веди — знак старословʼянської азбуки. Його сенс: Відаю, знаю. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'В', '#9a2b1e', '', '', '', '', 'uk', '3f879cc6-1a5c-449e-bcfc-b9cb915502b5', 'published'),
    ('vedi', 'В', 3, 'Веди', 'Ведаю, знаю', 'Веди говорит о знании не как о гордости, а как о внимательном ведении истины и смысла.', NULL, 'В', '#9a2b1e', '', '', '', '', 'ru', '3f879cc6-1a5c-449e-bcfc-b9cb915502b5', 'published'),
    ('vedi', 'В', 3, 'Веди', 'I know, I understand', 'Веди is a sign of the Old Slavonic alphabet. Its meaning: I know, I understand. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'В', '#9a2b1e', '', '', '', '', 'en', '3f879cc6-1a5c-449e-bcfc-b9cb915502b5', 'published'),
    ('glagoli', 'Г', 4, 'Глаголи', 'Говори, слово, мовлення', 'Глаголи — знак старословʼянської азбуки. Його сенс: Говори, слово, мовлення. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Г', '#1f3f66', '', '', '', '', 'uk', '03d8f89c-6ab0-4b84-895a-49ead247e228', 'published'),
    ('glagoli', 'Г', 4, 'Глаголи', 'Говори, слово, речь', 'Глаголи напоминает: слово должно быть живым, правдивым и добрым, потому что речь формирует сердце.', NULL, 'Г', '#1f3f66', '', '', '', '', 'ru', '03d8f89c-6ab0-4b84-895a-49ead247e228', 'published'),
    ('glagoli', 'Г', 4, 'Глаголи', 'Speak, word, speech', 'Глаголи is a sign of the Old Slavonic alphabet. Its meaning: Speak, word, speech. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Г', '#1f3f66', '', '', '', '', 'en', '03d8f89c-6ab0-4b84-895a-49ead247e228', 'published'),
    ('dobro', 'Д', 5, 'Добро', 'Добро, благо, добра справа', 'Добро — знак старословʼянської азбуки. Його сенс: Добро, благо, добра справа. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Д', '#9a2b1e', '', '', '', '', 'uk', '65c510a5-3ba3-4b8b-bed0-dc9f3875a189', 'published'),
    ('dobro', 'Д', 5, 'Добро', 'Добро, благо, доброе дело', 'Добро соединяет знание и поступок: истинное слово должно вести к милосердию и благому делу.', NULL, 'Д', '#9a2b1e', '', '', '', '', 'ru', '65c510a5-3ba3-4b8b-bed0-dc9f3875a189', 'published'),
    ('dobro', 'Д', 5, 'Добро', 'Goodness, blessing, good deed', 'Добро is a sign of the Old Slavonic alphabet. Its meaning: Goodness, blessing, good deed. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Д', '#9a2b1e', '', '', '', '', 'en', '65c510a5-3ba3-4b8b-bed0-dc9f3875a189', 'published')
ON CONFLICT (slug, language) DO NOTHING;

INSERT INTO church_alphabet_letters
    (slug, letter, sort_order, name, short_description, full_text, numeric_value,
     modern_equivalent, color, card_image_url, main_image_url, seo_title, seo_description,
     language, translation_group_id, status)
VALUES
    ('est', 'Є', 6, 'Есть', 'Є, існує, буття', 'Есть — знак старословʼянської азбуки. Його сенс: Є, існує, буття. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Е / Є', '#1f3f66', '', '', '', '', 'uk', '50eadc97-c06e-47a8-a63d-c7f53bdf1e0a', 'published'),
    ('est', 'Є', 6, 'Есть', 'Есть, существует, бытие', 'Есть указывает на бытие и присутствие: добро не только произносится, но существует и становится жизнью.', NULL, 'Е / Є', '#1f3f66', '', '', '', '', 'ru', '50eadc97-c06e-47a8-a63d-c7f53bdf1e0a', 'published'),
    ('est', 'Є', 6, 'Есть', 'Is, exists, being', 'Есть is a sign of the Old Slavonic alphabet. Its meaning: Is, exists, being. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Е / Є', '#1f3f66', '', '', '', '', 'en', '50eadc97-c06e-47a8-a63d-c7f53bdf1e0a', 'published'),
    ('zhivete', 'Ж', 7, 'Живете', 'Життя, живіть', 'Живете — знак старословʼянської азбуки. Його сенс: Життя, живіть. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Ж', '#9a2b1e', '', '', '', '', 'uk', 'ca205573-4d1b-4e3f-9b94-718117dcbc10', 'published'),
    ('zhivete', 'Ж', 7, 'Живете', 'Жизнь, живите', 'Живете звучит как призыв жить осмысленно, хранить душу и принимать жизнь как дар.', NULL, 'Ж', '#9a2b1e', '', '', '', '', 'ru', 'ca205573-4d1b-4e3f-9b94-718117dcbc10', 'published'),
    ('zhivete', 'Ж', 7, 'Живете', 'Life, live', 'Живете is a sign of the Old Slavonic alphabet. Its meaning: Life, live. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Ж', '#9a2b1e', '', '', '', '', 'en', 'ca205573-4d1b-4e3f-9b94-718117dcbc10', 'published'),
    ('dzelo', 'Ѕ', 8, 'Зело', 'Вельми, дуже', 'Зело — знак старословʼянської азбуки. Його сенс: Вельми, дуже. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'ДЗ', '#1f3f66', '', '', '', '', 'uk', '7efa5d5f-26f9-4083-a7b0-66703e9d685a', 'published'),
    ('dzelo', 'Ѕ', 8, 'Зело', 'Весьма, очень', 'Зело передавало звук дз и усиливало смысл: в древней книжности даже редкие буквы помогали точнее слышать слово.', NULL, 'ДЗ', '#1f3f66', '', '', '', '', 'ru', '7efa5d5f-26f9-4083-a7b0-66703e9d685a', 'published'),
    ('dzelo', 'Ѕ', 8, 'Зело', 'Very, greatly', 'Зело is a sign of the Old Slavonic alphabet. Its meaning: Very, greatly. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'ДЗ', '#1f3f66', '', '', '', '', 'en', '7efa5d5f-26f9-4083-a7b0-66703e9d685a', 'published'),
    ('zemlya', 'З', 9, 'Земля', 'Земля, світ', 'Земля — знак старословʼянської азбуки. Його сенс: Земля, світ. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'З', '#9a2b1e', '', '', '', '', 'uk', 'cbc36b37-b5b1-4180-abd1-c3960e4f8b16', 'published'),
    ('zemlya', 'З', 9, 'Земля', 'Земля, мир', 'Земля напоминает о мире, доме и творении, где человек призван трудиться и хранить порядок.', NULL, 'З', '#9a2b1e', '', '', '', '', 'ru', 'cbc36b37-b5b1-4180-abd1-c3960e4f8b16', 'published'),
    ('zemlya', 'З', 9, 'Земля', 'Earth, world', 'Земля is a sign of the Old Slavonic alphabet. Its meaning: Earth, world. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'З', '#9a2b1e', '', '', '', '', 'en', 'cbc36b37-b5b1-4180-abd1-c3960e4f8b16', 'published'),
    ('izhe', 'И', 10, 'Иже', 'Котрий, той', 'Иже — знак старословʼянської азбуки. Його сенс: Котрий, той. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'И', '#1f3f66', '', '', '', '', 'uk', 'c57c60c6-688b-46e0-b7d7-395d60fd9c0b', 'published'),
    ('izhe', 'И', 10, 'Иже', 'Который, тот', 'Иже связывает слова и смыслы, помогая древнему тексту звучать стройно и молитвенно.', NULL, 'И', '#1f3f66', '', '', '', '', 'ru', 'c57c60c6-688b-46e0-b7d7-395d60fd9c0b', 'published'),
    ('izhe', 'И', 10, 'Иже', 'Which, that one', 'Иже is a sign of the Old Slavonic alphabet. Its meaning: Which, that one. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'И', '#1f3f66', '', '', '', '', 'en', 'c57c60c6-688b-46e0-b7d7-395d60fd9c0b', 'published')
ON CONFLICT (slug, language) DO NOTHING;

INSERT INTO church_alphabet_letters
    (slug, letter, sort_order, name, short_description, full_text, numeric_value,
     modern_equivalent, color, card_image_url, main_image_url, seo_title, seo_description,
     language, translation_group_id, status)
VALUES
    ('i', 'І', 11, 'И', 'І, сполучник, рух звуку', 'И — знак старословʼянської азбуки. Його сенс: І, сполучник, рух звуку. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'И / Й', '#9a2b1e', '', '', '', '', 'uk', '84b7cba8-e8bd-4a8b-91e4-694816dd7e6b', 'published'),
    ('i', 'І', 11, 'И', 'И, союз, движение звука', 'Іота сохраняет греческую книжную память и показывает, как славянская азбука соединяла местную речь с церковной традицией.', NULL, 'И / Й', '#9a2b1e', '', '', '', '', 'ru', '84b7cba8-e8bd-4a8b-91e4-694816dd7e6b', 'published'),
    ('i', 'І', 11, 'И', 'And, conjunction, movement of sound', 'И is a sign of the Old Slavonic alphabet. Its meaning: And, conjunction, movement of sound. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'И / Й', '#9a2b1e', '', '', '', '', 'en', '84b7cba8-e8bd-4a8b-91e4-694816dd7e6b', 'published'),
    ('kako', 'К', 12, 'Како', 'Як, яким чином', 'Како — знак старословʼянської азбуки. Його сенс: Як, яким чином. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'К', '#1f3f66', '', '', '', '', 'uk', 'f8566e37-7195-4774-84b6-2857b63ab823', 'published'),
    ('kako', 'К', 12, 'Како', 'Как, каким образом', 'Како задает вопрос о пути: мало знать цель, важно понять, как идти к ней честно.', NULL, 'К', '#1f3f66', '', '', '', '', 'ru', 'f8566e37-7195-4774-84b6-2857b63ab823', 'published'),
    ('kako', 'К', 12, 'Како', 'How, in what way', 'Како is a sign of the Old Slavonic alphabet. Its meaning: How, in what way. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'К', '#1f3f66', '', '', '', '', 'en', 'f8566e37-7195-4774-84b6-2857b63ab823', 'published'),
    ('lyudi', 'Л', 13, 'Люди', 'Люди, народ', 'Люди — знак старословʼянської азбуки. Його сенс: Люди, народ. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Л', '#9a2b1e', '', '', '', '', 'uk', '05c8eabf-1ade-4b3b-bd2a-deb9a2562986', 'published'),
    ('lyudi', 'Л', 13, 'Люди', 'Люди, народ', 'Люди говорит о соборности: буквы и книги служили не одиночеству, а народу и общине.', NULL, 'Л', '#9a2b1e', '', '', '', '', 'ru', '05c8eabf-1ade-4b3b-bd2a-deb9a2562986', 'published'),
    ('lyudi', 'Л', 13, 'Люди', 'People, nation', 'Люди is a sign of the Old Slavonic alphabet. Its meaning: People, nation. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Л', '#9a2b1e', '', '', '', '', 'en', '05c8eabf-1ade-4b3b-bd2a-deb9a2562986', 'published'),
    ('myslete', 'М', 14, 'Мыслете', 'Мисліть, думайте', 'Мыслете — знак старословʼянської азбуки. Його сенс: Мисліть, думайте. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'М', '#1f3f66', '', '', '', '', 'uk', 'a4332624-39e7-4838-a8e7-a371831593cd', 'published'),
    ('myslete', 'М', 14, 'Мыслете', 'Мыслите, думайте', 'Мыслете призывает к рассуждению, вниманию и духовной трезвости в словах и поступках.', NULL, 'М', '#1f3f66', '', '', '', '', 'ru', 'a4332624-39e7-4838-a8e7-a371831593cd', 'published'),
    ('myslete', 'М', 14, 'Мыслете', 'Think, reflect', 'Мыслете is a sign of the Old Slavonic alphabet. Its meaning: Think, reflect. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'М', '#1f3f66', '', '', '', '', 'en', 'a4332624-39e7-4838-a8e7-a371831593cd', 'published'),
    ('nash', 'Н', 15, 'Нашъ', 'Наш', 'Нашъ — знак старословʼянської азбуки. Його сенс: Наш. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Н', '#9a2b1e', '', '', '', '', 'uk', '9e1fb3b7-641d-46d7-b2e8-efcea269cdf3', 'published'),
    ('nash', 'Н', 15, 'Нашъ', 'Наш', 'Нашъ хранит чувство принадлежности: вера, язык и память передаются как общее наследие.', NULL, 'Н', '#9a2b1e', '', '', '', '', 'ru', '9e1fb3b7-641d-46d7-b2e8-efcea269cdf3', 'published'),
    ('nash', 'Н', 15, 'Нашъ', 'Our', 'Нашъ is a sign of the Old Slavonic alphabet. Its meaning: Our. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Н', '#9a2b1e', '', '', '', '', 'en', '9e1fb3b7-641d-46d7-b2e8-efcea269cdf3', 'published')
ON CONFLICT (slug, language) DO NOTHING;

