VALUES
    ('on', 'О', 16, 'Онъ', 'Він', 'Онъ — знак старословʼянської азбуки. Його сенс: Він. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'О', '#1f3f66', '', '', '', '', 'uk', '9b3afd59-5340-4da6-9461-0f13380634ad', 'published'),
    ('on', 'О', 16, 'Онъ', 'Он', 'Онъ обращает взгляд от себя к Другому, к ближнему и к Богу, перед Которым слово становится ответственным.', NULL, 'О', '#1f3f66', '', '', '', '', 'ru', '9b3afd59-5340-4da6-9461-0f13380634ad', 'published'),
    ('on', 'О', 16, 'Онъ', 'He', 'Онъ is a sign of the Old Slavonic alphabet. Its meaning: He. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'О', '#1f3f66', '', '', '', '', 'en', '9b3afd59-5340-4da6-9461-0f13380634ad', 'published'),
    ('pokoy', 'П', 17, 'Покой', 'Мир, спокій', 'Покой — знак старословʼянської азбуки. Його сенс: Мир, спокій. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'П', '#9a2b1e', '', '', '', '', 'uk', '2186d297-32d5-49bc-9e73-8819b4f920a1', 'published'),
    ('pokoy', 'П', 17, 'Покой', 'Мир, покой', 'Покой напоминает о внутреннем мире, который рождается из молитвы, правды и добрых дел.', NULL, 'П', '#9a2b1e', '', '', '', '', 'ru', '2186d297-32d5-49bc-9e73-8819b4f920a1', 'published'),
    ('pokoy', 'П', 17, 'Покой', 'Peace, rest', 'Покой is a sign of the Old Slavonic alphabet. Its meaning: Peace, rest. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'П', '#9a2b1e', '', '', '', '', 'en', '2186d297-32d5-49bc-9e73-8819b4f920a1', 'published'),
    ('rtsy', 'Р', 18, 'Рцы', 'Говори, промов', 'Рцы — знак старословʼянської азбуки. Його сенс: Говори, промов. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Р', '#1f3f66', '', '', '', '', 'uk', 'e5989758-afce-4273-ab5c-8b16e00d0b38', 'published'),
    ('rtsy', 'Р', 18, 'Рцы', 'Говори, изреки', 'Рцы снова возвращает к речи: произнесенное слово должно быть ясным и достойным.', NULL, 'Р', '#1f3f66', '', '', '', '', 'ru', 'e5989758-afce-4273-ab5c-8b16e00d0b38', 'published'),
