    ('omega', 'Ѡ', 24, 'Отъ', 'Ot, omega, solemn O', 'Отъ is a sign of the Old Slavonic alphabet. Its meaning: Ot, omega, solemn O. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'О / Омега', '#1f3f66', '', '', '', '', 'en', 'a75d4c31-65d9-424c-a1ba-dcece1c77102', 'published'),
