    ('sha', 'Ш', 27, 'Ша', 'Буква Ш', 'Ша дает мягкую широту звучания, знакомую славянской речи и церковному чтению.', NULL, 'Ш', '#9a2b1e', '', '', '', '', 'ru', '0aee8420-55f4-4c14-999e-9c096a9d18ed', 'published'),
