    ('yat', 'Ѣ', 32, 'Ять', 'Древний звук ѣ', 'Ять стала знаком древней книжности: ее история показывает, как менялся язык и сохранялась память.', NULL, 'Ѣ', '#1f3f66', '', '', '', '', 'ru', '588147c5-11ef-4b8e-bf53-05cade2eccb8', 'published'),
    ('yat', 'Ѣ', 32, 'Ять', 'Ancient yat sound', 'Ять is a sign of the Old Slavonic alphabet. Its meaning: Ancient yat sound. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Ѣ', '#1f3f66', '', '', '', '', 'en', '588147c5-11ef-4b8e-bf53-05cade2eccb8', 'published'),
