    ('ya-iotated', 'Ꙗ', 33, 'Я', 'Йотированное А', 'Древняя буква Ꙗ передавала звук я и позже стала одной из основ современного знака Я.', NULL, 'Я', '#9a2b1e', '', '', '', '', 'ru', '992b0de6-8fa4-402d-83be-7c997a5ae30f', 'published'),
    ('ya-iotated', 'Ꙗ', 33, 'Я', 'Iotated A', 'Я is a sign of the Old Slavonic alphabet. Its meaning: Iotated A. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Я', '#9a2b1e', '', '', '', '', 'en', '992b0de6-8fa4-402d-83be-7c997a5ae30f', 'published'),
    ('ye', 'Ѥ', 34, 'Е йотированное', 'Йотоване Е', 'Е йотированное — знак старословʼянської азбуки. Його сенс: Йотоване Е. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'ЙЕ', '#1f3f66', '', '', '', '', 'uk', 'd494123a-25e5-4520-bc0f-11d3d6abd4d0', 'published'),
    ('ye', 'Ѥ', 34, 'Е йотированное', 'Йотированное Е', 'Ѥ помогала передавать начальное или мягкое йотированное звучание е в древних текстах.', NULL, 'ЙЕ', '#1f3f66', '', '', '', '', 'ru', 'd494123a-25e5-4520-bc0f-11d3d6abd4d0', 'published'),
    ('ye', 'Ѥ', 34, 'Е йотированное', 'Iotated E', 'Е йотированное is a sign of the Old Slavonic alphabet. Its meaning: Iotated E. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'ЙЕ', '#1f3f66', '', '', '', '', 'en', 'd494123a-25e5-4520-bc0f-11d3d6abd4d0', 'published'),
    ('yu', 'Ю', 35, 'Ю', 'Йотоване У', 'Ю — знак старословʼянської азбуки. Його сенс: Йотоване У. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Ю', '#9a2b1e', '', '', '', '', 'uk', 'fa46c5cf-509d-4ff6-9f3b-12b695fa826a', 'published'),
    ('yu', 'Ю', 35, 'Ю', 'Йотированное У', 'Ю соединяет мягкость и полноту звучания, завершая ряд букв, близких современному читателю.', NULL, 'Ю', '#9a2b1e', '', '', '', '', 'ru', 'fa46c5cf-509d-4ff6-9f3b-12b695fa826a', 'published'),
