INSERT INTO church_alphabet_letters
    (slug, letter, sort_order, name, short_description, full_text, numeric_value,
     modern_equivalent, color, card_image_url, main_image_url, seo_title, seo_description,
     language, translation_group_id, status)
VALUES
    ('psi', 'Ѱ', 41, 'Пси', 'Грецька літера псі', 'Пси — знак старословʼянської азбуки. Його сенс: Грецька літера псі. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'ПС', '#9a2b1e', '', '', '', '', 'uk', 'f25bcdf3-d900-412b-9a72-4fe5699b7740', 'published'),
    ('psi', 'Ѱ', 41, 'Пси', 'Греческая буква пси', 'Пси пришла из греческого письма и встречалась в церковных словах, именах и числовой записи.', NULL, 'ПС', '#9a2b1e', '', '', '', '', 'ru', 'f25bcdf3-d900-412b-9a72-4fe5699b7740', 'published'),
    ('psi', 'Ѱ', 41, 'Пси', 'Greek letter psi', 'Пси is a sign of the Old Slavonic alphabet. Its meaning: Greek letter psi. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'ПС', '#9a2b1e', '', '', '', '', 'en', 'f25bcdf3-d900-412b-9a72-4fe5699b7740', 'published'),
    ('fita', 'Ѳ', 42, 'Фита', 'Грецька theta', 'Фита — знак старословʼянської азбуки. Його сенс: Грецька theta. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Ф / Т', '#1f3f66', '', '', '', '', 'uk', '99969d7e-a287-4843-9bff-8ba4b6edced8', 'published'),
    ('fita', 'Ѳ', 42, 'Фита', 'Греческая theta', 'Фита передавала греческую theta и в славянском чтении часто сближалась с ф или т.', NULL, 'Ф / Т', '#1f3f66', '', '', '', '', 'ru', '99969d7e-a287-4843-9bff-8ba4b6edced8', 'published'),
    ('fita', 'Ѳ', 42, 'Фита', 'Greek theta', 'Фита is a sign of the Old Slavonic alphabet. Its meaning: Greek theta. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Ф / Т', '#1f3f66', '', '', '', '', 'en', '99969d7e-a287-4843-9bff-8ba4b6edced8', 'published'),
    ('izhitsa', 'Ѵ', 43, 'Ижица', 'Грецька upsilon', 'Ижица — знак старословʼянської азбуки. Його сенс: Грецька upsilon. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'И / В / Ю', '#9a2b1e', '', '', '', '', 'uk', '0a091e42-8e2e-4aac-83c9-33ca0eb9172f', 'published'),
    ('izhitsa', 'Ѵ', 43, 'Ижица', 'Греческая upsilon', 'Ижица связана с греческой традицией, встречалась в книжных словах и имела числовое значение.', NULL, 'И / В / Ю', '#9a2b1e', '', '', '', '', 'ru', '0a091e42-8e2e-4aac-83c9-33ca0eb9172f', 'published'),
    ('izhitsa', 'Ѵ', 43, 'Ижица', 'Greek upsilon', 'Ижица is a sign of the Old Slavonic alphabet. Its meaning: Greek upsilon. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'И / В / Ю', '#9a2b1e', '', '', '', '', 'en', '0a091e42-8e2e-4aac-83c9-33ca0eb9172f', 'published'),
    ('koppa', 'Ҁ', 44, 'Коппа', 'Коппа, числовий знак', 'Коппа — знак старословʼянської азбуки. Його сенс: Коппа, числовий знак. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'Числовой знак', '#1f3f66', '', '', '', '', 'uk', '53594344-56d4-463f-ae60-7fa9226633e7', 'published'),
    ('koppa', 'Ҁ', 44, 'Коппа', 'Коппа, знак числа', 'Коппа почти не имела звуковой роли и главным образом служила числовым знаком в ранней кириллице.', NULL, 'Числовой знак', '#1f3f66', '', '', '', '', 'ru', '53594344-56d4-463f-ae60-7fa9226633e7', 'published'),
    ('koppa', 'Ҁ', 44, 'Коппа', 'Koppa, a numeral sign', 'Коппа is a sign of the Old Slavonic alphabet. Its meaning: Koppa, a numeral sign. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'Числовой знак', '#1f3f66', '', '', '', '', 'en', '53594344-56d4-463f-ae60-7fa9226633e7', 'published'),
    ('ot', 'Ѿ', 45, 'От', 'Лігатура омега + твердо', 'От — знак старословʼянської азбуки. Його сенс: Лігатура омега + твердо. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'ОТ', '#9a2b1e', '', '', '', '', 'uk', 'ca7ee72d-7304-47fd-835a-7c8c53df8387', 'published'),
    ('ot', 'Ѿ', 45, 'От', 'Лигатура омега + твердо', 'Ѿ появилась как книжная лигатура для от и часто воспринимается как отдельный знак в расширенных азбучных таблицах.', NULL, 'ОТ', '#9a2b1e', '', '', '', '', 'ru', 'ca7ee72d-7304-47fd-835a-7c8c53df8387', 'published'),
    ('ot', 'Ѿ', 45, 'От', 'Ligature omega + tverdo', 'От is a sign of the Old Slavonic alphabet. Its meaning: Ligature omega + tverdo. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'ОТ', '#9a2b1e', '', '', '', '', 'en', 'ca7ee72d-7304-47fd-835a-7c8c53df8387', 'published')
ON CONFLICT (slug, language) DO NOTHING;

