VALUES
    ('djerv', 'Ꙉ', 46, 'Дервь', 'Регіональний знак південнословʼянської традиції', 'Дервь — знак старословʼянської азбуки. Його сенс: Регіональний знак південнословʼянської традиції. Такі літери зберігали звук, числову памʼять і книжну традицію давнього церковного письма.', NULL, 'ДЖ / Ђ', '#1f3f66', '', '', '', '', 'uk', 'bf76dcb8-0de8-48b3-9292-dda7e2d907f6', 'published'),
    ('djerv', 'Ꙉ', 46, 'Дервь', 'Региональный знак южнославянской традиции', 'Дервь встречался в ранних сербских памятниках; это региональный знак, поэтому именно он делает расширенный набор вариативным.', NULL, 'ДЖ / Ђ', '#1f3f66', '', '', '', '', 'ru', 'bf76dcb8-0de8-48b3-9292-dda7e2d907f6', 'published'),
    ('djerv', 'Ꙉ', 46, 'Дервь', 'Regional sign of the South Slavic tradition', 'Дервь is a sign of the Old Slavonic alphabet. Its meaning: Regional sign of the South Slavic tradition. These letters preserved sound, numerical memory, and the book tradition of early church writing.', NULL, 'ДЖ / Ђ', '#1f3f66', '', '', '', '', 'en', 'bf76dcb8-0de8-48b3-9292-dda7e2d907f6', 'published')
